 async function load(force=false){const u=currentUser(),key=(u?.id||'local')+':'+(u?.revogacao||0);if(!force&&S.loaded&&S.token===key&&S.at&&Date.now()-M.time(S.at)<60000){render();return;}if(S.token!==key){S.all=[];ac2.DEM=[];ac2.OBS=[];S.at=null;ac2.nivel=u?.perfil==='coordenacao'?'coord':u?.perfil==='gestor'?'gestor':'direcao';S.flash='';S.filter={search:'',status:'all',type:'',operation:'',gestor:'',order:'priority'};S.view='dashboard';S.trail=[];ac2.gestorSel=null;}const seq=++S.seq;S.token=key;S.loading=true;S.error='';S.loaded=false;render();try{let data;if(location.protocol==='file:'){data=ac2BuildDemandas();S.source='calculado no arquivo local';}else{const res=await authFetch('/api/demandas',{cache:'no-store'});if(!res.ok)throw Error(res.status===403?'Seu acesso não permite consultar esta fila.':'A consulta retornou HTTP '+res.status);data=await res.json();if(!Array.isArray(data))throw Error('Resposta da fila inválida');S.source='banco (API)';}if(seq!==S.seq)return;S.all=data;ac2.DEM=data.filter(i=>i.estado!=='aguardando');ac2.OBS=data.filter(i=>i.estado==='aguardando');ac2._fonte=S.source;S.at=new Date().toISOString();S.loaded=true;}catch(e){if(seq!==S.seq)return;S.all=[];ac2.DEM=[];ac2.OBS=[];S.error=e.message;S.source='consulta indisponível';}finally{if(seq===S.seq){S.loading=false;render();}}}
